UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 44, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 45, 7, NULL::text),(3, 173, 33, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 210, 858, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='03eb8be2-e854-5036-81c8-526dedddcba5' AND md5(a.contenido)='a314488040cef32bca9c95dc1ad79583' RETURNING a.id,md5(a.contenido) hash;